/**
 * Raw API types — the façade over `api.gen.ts` (generated by
 * `openapi-typescript`; regenerate with `bun run api:types`, never edit by
 * hand). Adds the runtime vocabulary (`..._STATUSES` arrays) a generated type
 * cannot provide, and `ApiUser`, which the OpenAPI document does not publish.
 * `api.contract.spec.ts` pins both to the generated unions.
 */

import type { components } from "./api.gen";

type Wire = components["schemas"];

export interface ApiUser {
  id: string;
  name: string | null;
  email: string;
  emailVerified: boolean;
  image?: string | null;
  createdAt: string;
  updatedAt: string;
}

/**
 * Lifecycle, in the order a posting moves through it. A const array so the
 * zeroed counters can enumerate the same statuses at runtime.
 */
export const REPLACEMENT_LISTING_STATUSES = [
  "DRAFT",
  "OPEN",
  "IN_DISCUSSION",
  "FULL",
  "FILLED",
  "CLOSED",
  "CLOSED_NO_CANDIDATE",
  "CANCELLED",
] as const;

export type ReplacementListingStatus =
  (typeof REPLACEMENT_LISTING_STATUSES)[number];

export type ApiReplacementListing = Wire["ReplacementListing"];

/**
 * Per-specialty totals; every specialty is present. Stricter than the
 * published `{ [key: string]: number }`, and pinned by a parity test.
 */
export type ApiListingSpecialtyCounts = Record<Specialty, number>;

export type ApiListingFacets = Wire["ListingFacets"];

export type ApiListingPlaces = Wire["ListingPlaces"];

/** One posting at a place, as the map's popup previews it. */
export type ApiPlaceListing =
  ApiListingPlaces["places"][number]["listings"][number];

export type ApiListingPlace = ApiListingPlaces["places"][number];

/**
 * The page of the reader's ordering that holds one posting, `null` when the
 * current filters do not show it.
 */
export type ApiListingPageOf = Wire["ListingPageOf"];

/**
 * One application. On the applicant, `anonymized` is the only trustworthy sign
 * the candidate erased their account: a blank name can also be one never filled.
 */
export type ApiApplication = Wire["Application"];

/**
 * One application as a paginated read answers it. Narrower than
 * `ApiApplication`: the embedded listing has no `description`, its practice no
 * address.
 */
export type ApiApplicationRow = Wire["PaginatedApplications"]["data"][number];

export const APPLICATION_STATUSES = [
  "PENDING",
  "SHORTLISTED",
  "ACCEPTED",
  "REJECTED",
  "WITHDRAWN",
] as const;

export type ApplicationStatus = (typeof APPLICATION_STATUSES)[number];

/**
 * Which outcome ended the application; null while it is open. Mirrors the
 * backend's `DecisionSource` enum. `SYSTEM` is an account erasure: `WITHDRAWN`
 * when the candidate erased theirs, `REJECTED` when the practice's went.
 */
export const APPLICATION_DECISION_SOURCES = [
  "CANDIDATE_WITHDREW",
  "PRACTICE_ACCEPTED",
  "PRACTICE_REJECTED",
  "SYSTEM",
] as const;

export type ApplicationDecisionSource =
  (typeof APPLICATION_DECISION_SOURCES)[number];

/** The three situations a rejected application can be, computed by the backend. */
export const APPLICATION_REJECTION_BUCKETS = [
  "PASSED_OVER",
  "POSTING_ENDED",
  "REFUSED",
] as const;

export type ApplicationRejectionBucket =
  (typeof APPLICATION_REJECTION_BUCKETS)[number];

/** Per-situation totals. Absent from an older backend; readers fill with 0. */
export type ApiApplicationBucketCounts = NonNullable<
  Wire["PaginatedApplications"]["meta"]["bucketCounts"]
>;

/**
 * A paginated response. `counts` is left to each caller: the endpoints break
 * their totals down by different status sets.
 */
export interface ApiPaginated<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

export interface ApiApplicationPage<T> extends ApiPaginated<T> {
  meta: ApiPaginated<T>["meta"] & {
    counts: ApiApplicationStatusCounts;
    /** Absent on older backends. */
    bucketCounts?: ApiApplicationBucketCounts;
    /** Open applications not yet viewed. Absent on older backends. */
    unseenOpenCount?: number;
    /** Applications that got an answer, withdrawn excluded — the response rate's numerator. */
    respondedCount?: number;
  };
}

/** One counter per value of `S`, plus the `total` across all of them. */
export type StatusCounts<S extends string> = Record<S | "total", number>;

export type ApiApplicationStatusCounts = StatusCounts<ApplicationStatus>;

/**
 * Ports of the backend's Prisma enums. `SPECIALTY_LABELS` and
 * `PROFILE_TYPE_LABELS` must enumerate exactly these; a parity test pins them.
 */
export type Specialty =
  | "GENERALIST"
  | "DENTIST"
  | "DERMATOLOGIST"
  | "PSYCHIATRIST"
  | "OTHER";

export type ProfileType = "INSTALLED" | "REPLACEMENT" | "BOTH";

export type ApiProfile = Wire["Profile"];
